  "claims": [
    {
      "claim": "Bumetanide, the same sulfamoylbenzoic acid loop diuretic class as furosemide, has L1 absolute oral bioavailability of 95% in patients with cirrhosis and L2 95-100%, directly supporting F >= 20% in the same condition.",
      "card_ids": ["C03","C21","C25"]
    },
    {
      "claim": "Additional cirrhosis-context L1 records show high oral bioavailability for metoclopramide (79-82%) and tolfenamic acid (about 91-100%), indicating that cirrhosis in this evidence set is associated with high F.",
      "card_ids": ["C06","C12","C13","C23","C05","C16"]
    },
    {
      "claim": "The closest structural analog azosemide has L1 absolute F of approximately 20.4% in healthy fasted humans, above the threshold; the L2 urinary-recovery estimate of 10% comes from healthy fasted subjects, not cirrhosis, and does not affirm F < 20% for the query.",
      "card_ids": ["C04","C27"]
    },
    {
      "claim": "L5 contains no furosemide-specific gut-wall efflux or intestinal metabolism measurement; the closest related diuretic records (HCTZ as ABCG2 substrate, indapamide Papp) are low-transferability and do not establish furosemide presystemic loss.",
      "card_ids": ["C174","C148","C181"]
    },
    {
      "claim": "L4 contains no furosemide-specific permeability or solubility measurement; C134 uses furosemide only as an inhibitor in a sulfasalazine Caco-2 assay, so it does not affirm F < 20%.",
      "card_ids": ["C134"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C174","C148","C181"]
    }
  ],
  "evidence_gaps": [
    "No direct furosemide-specific oral bioavailability or exposure record is present in any supplied level.",
    "No furosemide-specific gut-wall efflux or intestinal metabolism measurement is present in L5; related diuretic records (HCTZ, indapamide) are not directly transferable.",
    "Azosemide records conflict (L1 20.4% versus L2 10%) and come from healthy fasted subjects, not cirrhosis.",
    "Cirrhosis severity, formulation, and dose effects on furosemide absorption are unspecified.",
    "No furosemide-specific permeability or solubility measurement is present in L4; C134 uses furosemide only as an inhibitor."
  ],
  "decision_summary": "Predicted high (F >= 20%) because same-class same-condition L1 evidence (bumetanide in cirrhosis, F=95%) and multiple cirrhosis-context records support high F; the closest analog azosemide has L1 F=20.4% above threshold. L5 adds no furosemide-specific gut-wall efflux/intestinal metabolism evidence; related diuretic records are low-transferability and do not overturn the class-based evidence. Confidence remains moderate."
}

